    // Get the root node of the category tree
    CategoryNode rootNode = getRootNode();

    // Queue to store the inactive nodes to be removed
    Queue<CategoryNode> inactiveNodes = new LinkedList<>();

    // Iterate through the category tree and mark any inactive nodes
    // as well as their subsidiary inactive nodes to be removed
    rootNode.removeUnusedNodes(inactiveNodes);

    // Remove the inactive nodes from the category tree
    int numNodesRemoved = 0;
    while (!inactiveNodes.isEmpty()) {
        CategoryNode node = inactiveNodes.remove();
        if (node.getParent() != null) {
            node.getParent().removeChild(node);
            numNodesRemoved++;
        }
    }

    return numNodesRemoved;
}

