public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Initialize a list to store the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Iterate over the time ranges in the input list
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        // Get the start and end time of the current time range in milliseconds
        long startTime = timeRange.getStartTimeMillis();
        long endTime = timeRange.getEndTimeMillis();

        // Use the HprofReader to read the thread snapshots for the current time range
        try (HprofReader reader = new HprofReader(file)) {
            reader.setStartTime(startTime);
            reader.setEndTime(endTime);

            // Iterate over the thread snapshots in the current time range
            for (ThreadSnapshot threadSnapshot : reader.iterateThreadSnapshots()) {
                // Add each thread snapshot to the list
                threadSnapshots.add(threadSnapshot);
            }
        }
    }

    // Return the list of thread snapshots
    return threadSnapshots;
}
